    private static MeshData Build(ReadOnlySpan<float> positions, ReadOnlySpan<float> colors, ReadOnlySpan<float> normals, ReadOnlySpan<uint> indices)
    {
        var vertices = new VertexPositionColor[positions.Length / 3];
        for (var i = 0; i < vertices.Length; i++)
        {
            vertices[i] = new VertexPositionColor(new Vector3(positions[3 * i], positions[3 * i + 1], positions[3 * i + 2]), new Vector3(colors[3 * i], colors[3 * i + 1], colors[3 * i + 2]));
        }

        Vector3[]? normalArray = null;
        if (!normals.IsEmpty)
        {
            normalArray = new Vector3[vertices.Length];
            for (var i = 0; i < normalArray.Length; i++)
            {
                normalArray[i] = new Vector3(normals[3 * i], normals[3 * i + 1], normals[3 * i + 2]);
            }
        }

        return new MeshData(vertices, indices.ToArray()) { Normals = normalArray };
    }
